class BaseLoader:
    def load(self, env, name):
        return self.get_source(env, name)

    def get_source(self, env, name):
        raise NotImplementedError


class Environment:
    def __init__(self, loader: "BaseLoader" = None, **options):
        self.loader = loader
        self.options = options

    def get_template(self, name):
        return self.loader.load(self, name)
